using System.Buffers.Binary;
using System.Security.Cryptography;
using Meziantou.Framework.Imaging.Internals;
using Meziantou.Framework.Imaging.TestHarness.Avif;
using Meziantou.Framework.Imaging.TestHarness.Fixtures;
using Meziantou.Framework.Imaging.TestHarness.Golden;
using Meziantou.Framework.Imaging.Tests.Conformance.Hardening;
using Xunit.Sdk;

namespace Meziantou.Framework.Imaging.Tests.Conformance;

/// <summary>
/// The AV1 decoder against the conformance vectors generated by <c>tools/Meziantou.Framework.Imaging.CorpusGenerator/AvifCorpus.cs</c>:
/// raw OBU streams written by libaom and SVT-AV1, with the SHA-256 of every plane of every output frame as decoded, byte for
/// byte identically, by dav1d and by libaom when the corpus was generated. AV1 decoding is normative and bit-exact, film grain
/// synthesis included, so the planes the library decodes must have the same digests. The vectors are intra streams (key
/// frames) and inter streams: hidden frames produce no output, a frame shown again is output again, and the size of the
/// output frames can change inside a stream (reference scaling).
/// <para>
/// Layered vectors (<c>av1.spatial_layers</c>: the payload of the coded item of a layered image written by avifenc) hold a
/// frame per spatial layer in each temporal unit. Both decoders output the frame of the highest layer of a temporal unit,
/// which is what the vector records and what the decoder outputs by default. The frames of the lower layers have no
/// digest in such a vector; they have one in the vectors that are the same stream without the units of its higher layers
/// (<c>truncationOf</c> in their provenance), which both decoders decoded too: the output of
/// <see cref="Av1Decoder.OutputAllLayers"/> and of <see cref="Av1Decoder.MaxSpatialLayer"/> is compared with them.
/// </para>
/// </summary>
/// <remarks>
/// A plane digest is the SHA-256 of the samples of the plane, rows in order, exactly plane-width samples per row, 1 byte per
/// sample for 8-bit streams and 2 little-endian bytes for 10 and 12-bit streams, in bitstream order Y, U, V
/// (<see cref="Av1VectorSet.PlaneDigest"/>).
/// </remarks>
public sealed class Av1DecoderConformanceTests
{
    private static readonly string[] PlaneNames = ["Y", "U", "V"];

    public static TheoryData<string> Vectors => [.. GoldenCorpus.Default.Av1Vectors.Select(vector => vector.Id)];

    /// <summary>The vectors whose operating point has several spatial layers.</summary>
    public static TheoryData<string> LayeredVectors => [.. GoldenCorpus.Default.Av1Vectors.Where(vector => vector.HasFeatureKey(SpatialLayers)).Select(vector => vector.Id)];

    /// <summary>The layered vectors that are another vector without the units of its higher layers.</summary>
    public static TheoryData<string> TruncatedLayeredVectors => [.. GoldenCorpus.Default.Av1Vectors.Where(vector => GetTruncationSource(vector) is not null).Select(vector => vector.Id)];

    private const string SpatialLayers = "av1.spatial_layers";

    [Fact]
    public void TheCorpusHasVectors()
    {
        Assert.NotEmpty(GoldenCorpus.Default.Av1Vectors);
    }

    [Theory]
    [MemberData(nameof(Vectors))]
    public void DecodedPlanesHaveTheDigestsOfTheIndependentDecoders(string id)
    {
        AssertDecodedPlanes(id, AllocationScope.Create(ImageConfiguration.Default, id));
    }

    /// <summary>
    /// Second pass, against reads of uninitialized state: every buffer the decoder and the film grain synthesis rent is
    /// filled with a non-zero pattern beforehand (<see cref="DirtySlabPool"/>), instead of the zeros of a fresh allocation.
    /// The planes must still have the digests of the independent decoders.
    /// </summary>
    [Theory]
    [MemberData(nameof(Vectors))]
    public void DecodedPlanesDoNotDependOnTheContentOfRentedBuffers(string id)
    {
        var dirty = new DirtySlabPool();
        AssertDecodedPlanes(id, new AllocationScope(ImageConfiguration.Default.Limits, dirty.Pool, id));
        dirty.AssertEveryRentalWasDirty(id);
    }

    /// <summary>
    /// Third pass, by several workers: the post-processing filters of each frame run by bands of rows, whatever the size of
    /// the frame (<see cref="Av1PostFilter.TestIgnoreMinimumSize"/>), so that the bands cut every vector, the last one
    /// shorter than the others, and the tiles of a tile group are decoded by workers. A last pass decodes the tiles from
    /// the last one to the first one, each by the worker of its index modulo 3, with buffers that are not cleared
    /// (<see cref="Av1TileWorkers.TestReverseOrder"/>): a tile must depend on no other tile, and on nothing that a worker
    /// keeps from its previous tile. The planes must still have the digests of the independent decoders.
    /// </summary>
    [Theory]
    [MemberData(nameof(Vectors))]
    public void DecodedPlanesDoNotDependOnTheNumberOfWorkers(string id)
    {
        Av1PostFilter.TestIgnoreMinimumSize = true;
        try
        {
            foreach (var workers in (int[])[2, 3, 16])
            {
                AssertDecodedPlanes(id, AllocationScope.Create(ImageConfiguration.Default, id), workers);
            }

            Av1TileWorkers.TestReverseOrder = true;
            var dirty = new DirtySlabPool();
            AssertDecodedPlanes(id, new AllocationScope(ImageConfiguration.Default.Limits, dirty.Pool, id), maxDegreeOfParallelism: 3);
            dirty.AssertEveryRentalWasDirty(id);
        }
        finally
        {
            Av1PostFilter.TestIgnoreMinimumSize = false;
            Av1TileWorkers.TestReverseOrder = false;
        }
    }

    /// <summary>
    /// The vectors whose tiles workers decode (<see cref="DecodedPlanesDoNotDependOnTheNumberOfWorkers"/>): tile groups of
    /// several tiles, uniform and explicit tile sizes, superblocks of 64x64 and of 128x128, every chroma format, inter
    /// frames, and frames that keep the distributions of a tile other than the first one (<c>context_update_tile_id</c>)
    /// for the frames that follow them.
    /// </summary>
    [Fact]
    public void TheVectorsHaveTilesThatWorkersDecode()
    {
        var headers = new List<(string Id, Av1FrameHeader Header, Av1SequenceHeader Sequence, int FrameCount)>();
        foreach (var vector in GoldenCorpus.Default.Av1Vectors)
        {
            var frames = Decode(vector, AllocationScope.Create(ImageConfiguration.Default, vector.Id), decoder => { });
            try
            {
                headers.AddRange(frames.Where(frame => frame.Frame.Header.TileCount > 1).Select(frame => (vector.Id, frame.Frame.Header, frame.Frame.Sequence, frames.Count)));
            }
            finally
            {
                Release(frames);
            }
        }

        Assert.HasCountGreaterThanOrEqual(10, headers.Select(entry => entry.Id).Distinct(StringComparer.Ordinal).ToList());
        Assert.Contains(headers, entry => IsExplicitSpacing(entry.Header.MiColStarts.AsSpan(0, entry.Header.TileCols + 1)));
        Assert.Contains(headers, entry => entry.Header.TileRows > 1);
        Assert.Contains(headers, entry => entry.Sequence.Use128x128Superblock);
        Assert.Contains(headers, entry => !entry.Header.FrameIsIntra);
        Assert.Equal([1, 3], headers.Select(entry => entry.Sequence.PlaneCount).Distinct().Order().ToArray());
        Assert.Contains(headers, entry => entry.Sequence.SubsamplingX is 0 && entry.Sequence.PlaneCount is 3);
        Assert.Contains(headers, entry => entry.FrameCount > 1 && !entry.Header.DisableFrameEndUpdateCdf && entry.Header.ContextUpdateTileId is not 0);

        // Uniform spacing gives every tile but the last one the same width, and the last one no more
        static bool IsExplicitSpacing(ReadOnlySpan<int> starts)
        {
            for (var i = 1; i < starts.Length - 1; i++)
            {
                if (starts[i + 1] - starts[i] > starts[1] - starts[0] || (i < starts.Length - 2 && starts[i + 1] - starts[i] != starts[1] - starts[0]))
                    return true;
            }

            return false;
        }
    }

    /// <summary>
    /// The tiles of a frame decoded by workers fail with the error of a sequential decoding: the error of the first tile
    /// that fails, whichever tile a worker finishes first. The data of one or two tiles of the first frame of each vector
    /// are overwritten, and the size of a tile is made larger than the data; the outcome (the error, or the digest of the
    /// frames) of 16 workers, and of 3 workers that decode the tiles from the last one, is the outcome of one worker.
    /// </summary>
    [Theory]
    [InlineData("av1/tiles-4x1-uniform-420-200x64", true)]
    [InlineData("av1/tiles-4x1-explicit-420-264x64", true)]
    [InlineData("av1/tiles-2x2-420-200x152", false)]
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Security", "CA5394:Do not use insecure randomness", Justification = "Deterministic seeded test inputs.")]
    public void TilesDecodedByWorkersFailWithTheErrorOfTheFirstFailingTile(string id, bool tilesFail)
    {
        var vector = GoldenCorpus.Default.GetAv1Vector(id);
        var data = File.ReadAllBytes(GoldenCorpus.Default.RootDirectory / vector.Input.Path);
        var (tiles, sizeFields, tileSizeBytes) = LocateTiles(data);
        Assert.HasCount(4, tiles);

        // A fill below 256 is that byte; above, the seed of random bytes
        int[] fills = [0x00, 0xFF, 1000, 1001, 1002];
        Av1PostFilter.TestIgnoreMinimumSize = true;
        try
        {
            var single = new Dictionary<(int Tile, int Fill), string>();
            foreach (var tile in Enumerable.Range(0, tiles.Count))
            {
                foreach (var fill in fills)
                {
                    single[(tile, fill)] = AssertSameOutcome(id, Fill(data, tiles[tile], fill));
                }
            }

            var distinctErrors = 0;
            for (var first = 0; first < tiles.Count; first++)
            {
                for (var second = first + 1; second < tiles.Count; second++)
                {
                    foreach (var firstFill in fills)
                    {
                        foreach (var secondFill in fills)
                        {
                            var outcome = AssertSameOutcome(id, Fill(Fill(data, tiles[first], firstFill), tiles[second], secondFill));
                            var (firstOutcome, secondOutcome) = (single[(first, firstFill)], single[(second, secondFill)]);
                            if (IsError(firstOutcome))
                                Assert.Equal(firstOutcome, outcome, message: $"{id}: tiles {first} ({firstFill}) and {second} ({secondFill}).");

                            if (IsError(firstOutcome) && IsError(secondOutcome) && firstOutcome != secondOutcome)
                                distinctErrors++;
                        }
                    }
                }
            }

            // A tile size that exceeds the data: the tiles before it are decoded, and their error comes first
            for (var tile = 1; tile < sizeFields.Count; tile++)
            {
                var corrupted = Fill(data, (sizeFields[tile], tileSizeBytes), 0xFF);
                var sizeError = AssertSameOutcome(id, corrupted);
                Assert.True(IsError(sizeError));
                foreach (var fill in fills)
                {
                    var outcome = AssertSameOutcome(id, Fill(corrupted, tiles[0], fill));
                    if (IsError(single[(0, fill)]))
                    {
                        Assert.Equal(single[(0, fill)], outcome);
                        if (sizeError != single[(0, fill)])
                            distinctErrors++;
                    }
                }
            }

            // Failures that differ, where the first one decides the error. The tiles of some vectors decode whatever their
            // data are: only the sizes of their tiles fail
            Assert.Equal(tilesFail, distinctErrors > 0, message: $"{id}: {distinctErrors} pairs of failures that differ. Errors: {string.Join(" | ", single.Values.Where(IsError).Distinct(StringComparer.Ordinal))}");
        }
        finally
        {
            Av1PostFilter.TestIgnoreMinimumSize = false;
        }

        static bool IsError(string outcome) => !outcome.StartsWith("frames:", StringComparison.Ordinal);

        static byte[] Fill(byte[] data, (int Offset, int Length) range, int fill)
        {
            var copy = data.ToArray();
            var target = copy.AsSpan(range.Offset, range.Length);
            if (fill < 256)
            {
                target.Fill((byte)fill);
            }
            else
            {
                new Random(fill).NextBytes(target);
            }

            return copy;
        }
    }

    [Fact]
    public void TileWorkersThrowTheErrorOfTheFirstFailingTileAndACancellationFirst()
    {
        var failures = new[] { new InvalidImageContentException("tile 3"), new InvalidImageContentException("tile 6") };
        foreach (var reverse in (bool[])[false, true])
        {
            Av1TileWorkers.TestReverseOrder = reverse;
            try
            {
                foreach (var workers in (int[])[1, 2, 3, 16])
                {
                    var ran = new int[10];
                    var exception = Assert.Throws<InvalidImageContentException>(() => Av1TileWorkers.Run(workers, 10, (worker, tile) =>
                    {
                        Assert.InRange(worker, 0, workers - 1);
                        Interlocked.Increment(ref ran[tile]);
                        switch (tile)
                        {
                            case 3:
                                throw failures[0];
                            case 6:
                                throw failures[1];
                        }
                    }));

                    Assert.Same(failures[0], exception);
                    Assert.All(ran.Take(4), count => count is 1, $"{workers} workers: a tile before the first failing one did not run once.");
                    Assert.All(ran, count => count <= 1, $"{workers} workers: a tile ran twice.");

                    // A cancellation that a tile observes comes before the errors of the other tiles: tile 7 runs when the
                    // tiles run from the last one, and may run with several workers
                    var canceled = new OperationCanceledException();
                    var failure = Assert.ThrowsAny<Exception>(() => Av1TileWorkers.Run(workers, 10, (worker, tile) =>
                    {
                        switch (tile)
                        {
                            case 2:
                                throw failures[0];
                            case 7:
                                throw canceled;
                        }
                    }));

                    if (reverse)
                    {
                        Assert.Same(canceled, failure);
                    }
                    else if (workers is 1)
                    {
                        Assert.Same(failures[0], failure);
                    }
                    else
                    {
                        Assert.True(ReferenceEquals(failure, canceled) || ReferenceEquals(failure, failures[0]), $"{workers} workers: {failure}");
                    }
                }
            }
            finally
            {
                Av1TileWorkers.TestReverseOrder = false;
            }
        }
    }

    [Fact]
    public void TileWorkersAreChargedToTheScopeBeforeTheTilesStart()
    {
        // The state of every worker is rented on the calling thread: the peak of a decoding by 4 workers is the same at
        // every run, above the one of a single worker, and a limit that only one worker fits fails before any output
        var vector = GoldenCorpus.Default.GetAv1Vector("av1/tiles-2x2-420-200x152");
        var data = File.ReadAllBytes(GoldenCorpus.Default.RootDirectory / vector.Input.Path);
        Av1PostFilter.TestIgnoreMinimumSize = true;
        try
        {
            var one = MeasurePeak(data, ImageConfiguration.Default.Limits, workers: 1);
            var four = MeasurePeak(data, ImageConfiguration.Default.Limits, workers: 4);
            Assert.True(four > one, $"{four} bytes with 4 workers, {one} with one.");
            Assert.Equal(four, MeasurePeak(data, ImageConfiguration.Default.Limits, workers: 4));

            var limits = new ImageResourceLimits { MaxLiveAllocationBytes = one };
            Assert.Equal(one, MeasurePeak(data, limits, workers: 1));
            var scope = new AllocationScope(limits, name: vector.Id);
            Assert.Throws<ImageResourceLimitException>(() => Decode(data, scope, decoder => decoder.MaxDegreeOfParallelism = 4));
            Assert.Equal(0, scope.LiveBytes);
        }
        finally
        {
            Av1PostFilter.TestIgnoreMinimumSize = false;
        }

        static long MeasurePeak(byte[] data, ImageResourceLimits limits, int workers)
        {
            var scope = new AllocationScope(limits, name: nameof(TileWorkersAreChargedToTheScopeBeforeTheTilesStart));
            Release(Decode(data, scope, decoder => decoder.MaxDegreeOfParallelism = workers));
            Assert.Equal(0, scope.LiveBytes);
            return scope.GetDiagnostics().PeakLiveBytes;
        }
    }

    [Fact]
    public void TilesDecodedByWorkersObserveTheCancellation()
    {
        var vector = GoldenCorpus.Default.GetAv1Vector("av1/tiles-2x2-420-200x152");
        var data = File.ReadAllBytes(GoldenCorpus.Default.RootDirectory / vector.Input.Path);
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        Av1PostFilter.TestIgnoreMinimumSize = true;
        try
        {
            var scope = AllocationScope.Create(ImageConfiguration.Default, vector.Id);
            using var decoder = new Av1Decoder(scope) { MaxDegreeOfParallelism = 4 };
            decoder.SetInput(data, 0, data.Length);
            Assert.Throws<OperationCanceledException>(() => decoder.DecodeNextOutputFrame(cancellation.Token));
        }
        finally
        {
            Av1PostFilter.TestIgnoreMinimumSize = false;
        }
    }

    // The outcome of the decoding of a stream, the same by one worker, by 16 workers and by 3 workers that decode the
    // tiles from the last one: the error, or the digest of the planes of every frame
    private static string AssertSameOutcome(string id, byte[] data)
    {
        var expected = GetOutcome(data, workers: 1);
        Assert.Equal(expected, GetOutcome(data, workers: 16), message: $"{id}: 16 workers.");
        Av1TileWorkers.TestReverseOrder = true;
        try
        {
            Assert.Equal(expected, GetOutcome(data, workers: 3), message: $"{id}: 3 workers, from the last tile.");
        }
        finally
        {
            Av1TileWorkers.TestReverseOrder = false;
        }

        return expected;

        static string GetOutcome(byte[] data, int workers)
        {
            var scope = AllocationScope.Create(ImageConfiguration.Default, nameof(AssertSameOutcome));
            try
            {
                var frames = Decode(data, scope, decoder => decoder.MaxDegreeOfParallelism = workers);
                try
                {
                    return "frames: " + string.Join(", ", frames.Select(frame => string.Join('/', Enumerable.Range(0, frame.Frame.PlaneCount).Select(plane => ComputeDigest(CopyOutputPlanes(scope, frame.Frame)[plane], frame.Frame.Sequence.BitDepth)))));
                }
                finally
                {
                    Release(frames);
                }
            }
            catch (ImageException exception)
            {
                return $"{exception.GetType().Name}: {exception.Message}";
            }
        }
    }

    // The tiles of the first frame of a stream that starts with a sequence header and a frame unit of one tile group: the
    // offset and the length of the data of each tile, the offsets of the tile_size_minus_1 fields, and their size
    private static (List<(int Offset, int Length)> Tiles, List<int> SizeFields, int TileSizeBytes) LocateTiles(byte[] data)
    {
        var units = ReferenceObuStream.ReadUnits(data);
        var sequenceUnit = units.First(unit => unit.Type == ReferenceObuStream.SequenceHeader);
        var sequence = Av1SequenceHeader.Parse(data.AsSpan(sequenceUnit.Offset + sequenceUnit.HeaderLength, sequenceUnit.PayloadLength), operatingPoint: 0);
        var frameUnit = units.First(unit => unit.Type == ReferenceObuStream.Frame);
        var obu = Av1ObuHeader.Read(data.AsSpan(frameUnit.Offset));
        var payloadStart = frameUnit.Offset + frameUnit.HeaderLength;
        var reader = new Av1BitReader(data.AsSpan(payloadStart, frameUnit.PayloadLength));
        var header = Av1FrameHeaderParser.Parse(ref reader, sequence, obu, new Av1FrameBuffer?[Av1Constants.NumRefFrames], new bool[Av1Constants.NumRefFrames]);
        Assert.True(header.FrameIsIntra);
        reader.ByteAlign();

        // tile_start_and_end_present_flag is 0 in a frame unit: one byte with the alignment
        var position = payloadStart + reader.BytePosition + 1;
        var end = payloadStart + frameUnit.PayloadLength;
        var tiles = new List<(int Offset, int Length)>();
        var sizeFields = new List<int>();
        for (var tile = 0; tile < header.TileCount; tile++)
        {
            if (tile == header.TileCount - 1)
            {
                tiles.Add((position, end - position));
                break;
            }

            sizeFields.Add(position);
            var size = 1;
            for (var i = 0; i < header.TileSizeBytes; i++)
            {
                size += data[position + i] << (8 * i);
            }

            position += header.TileSizeBytes;
            tiles.Add((position, size));
            position += size;
        }

        return (tiles, sizeFields, header.TileSizeBytes);
    }

    [Fact]
    public void LayeredVectorsCoverTheLayerCountsAndTheLowerLayers()
    {
        var layered = GoldenCorpus.Default.Av1Vectors.Where(vector => vector.HasFeatureKey(SpatialLayers)).ToList();
        var whole = layered.Where(vector => GetTruncationSource(vector) is null).ToList();
        foreach (var count in new[] { 2, 3, 4 })
        {
            Assert.Contains(whole, vector => GetLayerCount(vector) == count);

            // Every lower layer of a stream of that many layers has digests of its own: the truncated vectors
            var truncated = layered.Where(vector => GetTruncationSource(vector) is { } source && GetLayerCount(GoldenCorpus.Default.GetAv1Vector(source)) == count).Select(GetPresentLayerCount).Distinct().Order().ToArray();
            Assert.Equal([.. Enumerable.Range(1, count - 1)], truncated);
        }

        // Layers of the size of the image and layers of growing sizes, 8 to 12 bits, every subsampling, several temporal units
        Assert.Contains(whole, vector => vector.HasFeatureKey("av1.spatial_layer_sizes"));
        Assert.Contains(whole, vector => !vector.HasFeatureKey("av1.spatial_layer_sizes"));
        Assert.Equal([8, 10, 12], whole.Select(vector => vector.BitDepth).Distinct().Order().ToArray());
        Assert.Equal(["4:0:0", "4:2:0", "4:2:2", "4:4:4"], whole.Select(vector => vector.Subsampling).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray());
        Assert.Contains(whole, vector => vector.FrameCount > 1);
        Assert.Contains(layered, vector => GetTruncationSource(vector) is not null && vector.Frames[0].Width < GoldenCorpus.Default.GetAv1Vector(GetTruncationSource(vector)!).Frames[0].Width);
    }

    [Theory]
    [MemberData(nameof(LayeredVectors))]
    public void DefaultOutputIsTheHighestLayerOfEachTemporalUnit(string id)
    {
        // One frame per temporal unit (the recorded frames, which DecodedPlanesHaveTheDigestsOfTheIndependentDecoders
        // compares): its layer is the highest one the stream holds
        var vector = GoldenCorpus.Default.GetAv1Vector(id);
        var scope = AllocationScope.Create(ImageConfiguration.Default, id);
        var frames = Decode(vector, scope, decoder => { });
        try
        {
            Assert.HasCount(vector.FrameCount, frames);
            for (var i = 0; i < frames.Count; i++)
            {
                Assert.Equal(GetPresentLayerCount(vector) - 1, frames[i].SpatialId);
                AssertFrame(vector, i, scope, frames[i].Frame);
            }
        }
        finally
        {
            Release(frames);
        }
    }

    [Theory]
    [MemberData(nameof(LayeredVectors))]
    public void EveryLayerIsOutputAndTheLastOneHasTheDigestsOfTheIndependentDecoders(string id)
    {
        // The output of a conformance test: every shown frame, in bitstream order. A temporal unit of these vectors holds
        // one frame per layer, from the first layer to the last one, which is the recorded frame
        var vector = GoldenCorpus.Default.GetAv1Vector(id);
        var layers = GetPresentLayerCount(vector);
        var sizes = GetLayerSizes(vector);
        var scope = AllocationScope.Create(ImageConfiguration.Default, id);
        var frames = Decode(vector, scope, decoder => decoder.OutputAllLayers = true);
        try
        {
            Assert.HasCount(layers * vector.FrameCount, frames, $"{id}: the number of output frames is not the number of layers of every temporal unit.");
            for (var i = 0; i < frames.Count; i++)
            {
                var layer = i % layers;
                Assert.Equal(layer, frames[i].SpatialId, message: $"{id} frame {i}: spatial layer.");
                var plane = frames[i].Frame.GetPlane(0);
                if (sizes is not null)
                    Assert.Equal(sizes[layer], (plane.Width, plane.Height), message: $"{id} frame {i}: the size of layer {layer}.");

                if (layer == layers - 1)
                    AssertFrame(vector, i / layers, scope, frames[i].Frame);
            }
        }
        finally
        {
            Release(frames);
        }
    }

    [Theory]
    [MemberData(nameof(TruncatedLayeredVectors))]
    public void LowerLayersHaveTheDigestsOfTheStreamWithoutItsHigherLayers(string id)
    {
        // The truncated vector is the stream of its source without the units of the layers above the kept ones, decoded by
        // dav1d and libaom: its frame is the frame of the last kept layer. The decoder must give the same planes for that
        // layer of the whole stream, when it is asked for every layer and when the higher layers are left out
        var truncated = GoldenCorpus.Default.GetAv1Vector(id);
        var source = GoldenCorpus.Default.GetAv1Vector(GetTruncationSource(truncated)!);
        var kept = GetPresentLayerCount(truncated);
        var layers = GetLayerCount(source);
        Assert.Equal(kept, truncated.Provenance.Parameters!.Value.GetProperty("keptSpatialLayers").GetInt32());
        Assert.True(kept < layers && GetPresentLayerCount(source) == layers, $"{id}: the source holds every layer.");
        Assert.Equal(source.FrameCount, truncated.FrameCount);

        var scope = AllocationScope.Create(ImageConfiguration.Default, id);
        var everyLayer = Decode(source, scope, decoder => decoder.OutputAllLayers = true);
        try
        {
            Assert.HasCount(layers * source.FrameCount, everyLayer);
            for (var unit = 0; unit < source.FrameCount; unit++)
            {
                var frame = everyLayer[(unit * layers) + kept - 1];
                Assert.Equal(kept - 1, frame.SpatialId);
                AssertFrame(truncated, unit, scope, frame.Frame);
            }
        }
        finally
        {
            Release(everyLayer);
        }

        foreach (var outputAllLayers in new[] { false, true })
        {
            // With the higher layers left out, the frame of the selected layer is the last one of its temporal unit
            var limited = Decode(source, scope, decoder =>
            {
                decoder.MaxSpatialLayer = kept - 1;
                decoder.OutputAllLayers = outputAllLayers;
            });
            try
            {
                var perUnit = outputAllLayers ? kept : 1;
                Assert.HasCount(perUnit * source.FrameCount, limited, $"{id}: MaxSpatialLayer = {kept - 1}, OutputAllLayers = {outputAllLayers}.");
                for (var unit = 0; unit < source.FrameCount; unit++)
                {
                    var frame = limited[(unit * perUnit) + perUnit - 1];
                    Assert.Equal(kept - 1, frame.SpatialId);
                    AssertFrame(truncated, unit, scope, frame.Frame);
                }
            }
            finally
            {
                Release(limited);
            }
        }
    }

    [Theory]
    [MemberData(nameof(LayeredVectors))]
    public void MaxSpatialLayerOfTheLastLayerOrAboveChangesNothing(string id)
    {
        var vector = GoldenCorpus.Default.GetAv1Vector(id);
        var scope = AllocationScope.Create(ImageConfiguration.Default, id);
        for (var maximum = GetPresentLayerCount(vector) - 1; maximum <= Av1ObuHeader.MaxSpatialId; maximum++)
        {
            var frames = Decode(vector, scope, decoder => decoder.MaxSpatialLayer = maximum);
            try
            {
                Assert.HasCount(vector.FrameCount, frames, $"{id}: MaxSpatialLayer = {maximum}.");
                for (var i = 0; i < frames.Count; i++)
                {
                    Assert.Equal(GetPresentLayerCount(vector) - 1, frames[i].SpatialId);
                    AssertFrame(vector, i, scope, frames[i].Frame);
                }
            }
            finally
            {
                Release(frames);
            }
        }
    }

    [Theory]
    [InlineData("av1/intra-420-8bit-8x8")]
    [InlineData("av1/inter-alt-ref-420-8bit-16x16")]
    public void OutputPolicyDoesNotChangeAStreamWithoutLayers(string id)
    {
        // No scalability information: every shown frame is output whatever the policy, and its layer is 0
        var vector = GoldenCorpus.Default.GetAv1Vector(id);
        Assert.False(vector.HasFeatureKey(SpatialLayers));
        var scope = AllocationScope.Create(ImageConfiguration.Default, id);
        foreach (var (outputAllLayers, maximum) in new[] { (false, 3), (true, 3), (false, 0), (true, 0) })
        {
            var frames = Decode(vector, scope, decoder =>
            {
                decoder.OutputAllLayers = outputAllLayers;
                decoder.MaxSpatialLayer = maximum;
            });
            try
            {
                Assert.HasCount(vector.FrameCount, frames, $"{id}: OutputAllLayers = {outputAllLayers}, MaxSpatialLayer = {maximum}.");
                for (var i = 0; i < frames.Count; i++)
                {
                    Assert.Equal(0, frames[i].SpatialId);
                    AssertFrame(vector, i, scope, frames[i].Frame);
                }
            }
            finally
            {
                Release(frames);
            }
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void TemporalUnitEndsWithoutDelimiterAtAFrameOfTheSameOrOfALowerLayer(bool outputAllLayers)
    {
        // The samples and the items of an AVIF file need no temporal delimiter. Two layered pictures one after the other,
        // without any delimiter: the first frame of the second picture is of layer 0, so it starts a temporal unit, and the
        // frame of the highest layer of the first picture is output before it is decoded
        var vector = GoldenCorpus.Default.GetAv1Vector("av1/layered-2-temporal-units-420-8bit-32x32");
        Assert.Equal(2, vector.FrameCount);
        var data = File.ReadAllBytes(GoldenCorpus.Default.RootDirectory / vector.Input.Path);
        Assert.Equal(2, ReferenceObuStream.ReadUnits(data).Count(unit => unit.Type == ReferenceObuStream.TemporalDelimiter));
        var stream = ReferenceObuStream.Remove(data, unit => unit.Type == ReferenceObuStream.TemporalDelimiter);
        Assert.HasCount(data.Length - 4, stream);
        Assert.Equal([0, 1, 0, 1], ReferenceObuStream.ReadUnits(stream).Where(unit => unit.Type == ReferenceObuStream.Frame).Select(unit => unit.SpatialId).ToArray());

        var scope = AllocationScope.Create(ImageConfiguration.Default, vector.Id);
        var frames = Decode(stream, scope, decoder => decoder.OutputAllLayers = outputAllLayers);
        try
        {
            var perUnit = outputAllLayers ? 2 : 1;
            Assert.HasCount(perUnit * 2, frames);
            for (var unit = 0; unit < 2; unit++)
            {
                var frame = frames[(unit * perUnit) + perUnit - 1];
                Assert.Equal(1, frame.SpatialId);
                AssertFrame(vector, unit, scope, frame.Frame);
            }
        }
        finally
        {
            Release(frames);
        }
    }

    [Fact]
    public void TemporalUnitEndsAtTheEndOfTheInput()
    {
        // The decoder of an image sequence is given one sample at a time: the frame of the highest layer of a sample is
        // output at the end of its data, and the next sample is another temporal unit
        var vector = GoldenCorpus.Default.GetAv1Vector("av1/layered-2-temporal-units-420-8bit-32x32");
        var data = File.ReadAllBytes(GoldenCorpus.Default.RootDirectory / vector.Input.Path);
        var delimiters = ReferenceObuStream.ReadUnits(data).Where(unit => unit.Type == ReferenceObuStream.TemporalDelimiter).Select(unit => unit.Offset).ToArray();
        Assert.HasCount(2, delimiters);
        Assert.Equal(0, delimiters[0]);
        var scope = AllocationScope.Create(ImageConfiguration.Default, vector.Id);
        using var decoder = new Av1Decoder(scope);
        foreach (var (unit, offset, length) in new[] { (0, 0, delimiters[1]), (1, delimiters[1], data.Length - delimiters[1]) })
        {
            decoder.SetInput(data, offset, length);
            var frame = decoder.DecodeNextOutputFrame(TestContext.Current.CancellationToken);
            Assert.NotNull(frame);
            try
            {
                Assert.Equal(1, decoder.OutputSpatialId);
                AssertFrame(vector, unit, scope, frame);
            }
            finally
            {
                frame.Release();
            }

            Assert.Null(decoder.DecodeNextOutputFrame(TestContext.Current.CancellationToken));
        }
    }

    /// <summary>The number of spatial layers of the operating point of a layered vector (<c>av1.spatial_layers=N</c>).</summary>
    private static int GetLayerCount(Av1VectorEntry vector) => GetFeatureValue(vector, SpatialLayers + "=") ?? throw new XunitException($"{vector.Id} is not a layered vector.");

    /// <summary>The number of spatial layers a layered vector holds: every layer of its operating point, unless the units
    /// of the higher ones were removed (<c>av1.spatial_layers.present=N</c>).</summary>
    private static int GetPresentLayerCount(Av1VectorEntry vector) => GetFeatureValue(vector, SpatialLayers + ".present=") ?? GetLayerCount(vector);

    private static int? GetFeatureValue(Av1VectorEntry vector, string prefix)
    {
        var feature = vector.Features.SingleOrDefault(candidate => candidate.StartsWith(prefix, StringComparison.Ordinal));
        return feature is null ? null : int.Parse(feature[prefix.Length..], NumberStyles.None, CultureInfo.InvariantCulture);
    }

    /// <summary>The size of the frame of each layer, when the layers have different sizes (<c>av1.spatial_layer_sizes</c>).</summary>
    private static (int Width, int Height)[]? GetLayerSizes(Av1VectorEntry vector)
    {
        const string Prefix = "av1.spatial_layer_sizes=";
        var feature = vector.Features.SingleOrDefault(candidate => candidate.StartsWith(Prefix, StringComparison.Ordinal));
        return feature is null ? null : [.. feature[Prefix.Length..].Split(',').Select(size => size.Split('x')).Select(parts => (int.Parse(parts[0], CultureInfo.InvariantCulture), int.Parse(parts[1], CultureInfo.InvariantCulture)))];
    }

    /// <summary>The identifier of the vector that a vector is a truncation of, as its provenance records it.</summary>
    private static string? GetTruncationSource(Av1VectorEntry vector) =>
        vector.Provenance.Parameters is { } parameters && parameters.TryGetProperty("truncationOf", out var source) ? source.GetString() : null;

    private static List<(Av1FrameBuffer Frame, int SpatialId)> Decode(Av1VectorEntry vector, AllocationScope scope, Action<Av1Decoder> configure) =>
        Decode(File.ReadAllBytes(GoldenCorpus.Default.RootDirectory / vector.Input.Path), scope, configure);

    /// <summary>Every frame the decoder outputs for a stream, with the spatial layer it reports for it. The caller releases the frames.</summary>
    private static List<(Av1FrameBuffer Frame, int SpatialId)> Decode(byte[] data, AllocationScope scope, Action<Av1Decoder> configure)
    {
        var frames = new List<(Av1FrameBuffer Frame, int SpatialId)>();
        using var decoder = new Av1Decoder(scope);
        configure(decoder);
        decoder.SetInput(data, 0, data.Length);
        try
        {
            while (decoder.DecodeNextOutputFrame(TestContext.Current.CancellationToken) is { } frame)
            {
                frames.Add((frame, decoder.OutputSpatialId));
            }
        }
        catch
        {
            Release(frames);
            throw;
        }

        return frames;
    }

    private static void Release(List<(Av1FrameBuffer Frame, int SpatialId)> frames)
    {
        foreach (var (frame, _) in frames)
        {
            frame.Release();
        }
    }

    private static void AssertDecodedPlanes(string id, AllocationScope scope, int maxDegreeOfParallelism = 1)
    {
        var vector = GoldenCorpus.Default.GetAv1Vector(id);
        var data = File.ReadAllBytes(GoldenCorpus.Default.RootDirectory / vector.Input.Path);
        using var decoder = new Av1Decoder(scope) { MaxDegreeOfParallelism = maxDegreeOfParallelism };
        decoder.SetInput(data, 0, data.Length);

        var frameIndex = 0;
        while (decoder.DecodeNextOutputFrame(TestContext.Current.CancellationToken) is { } frame)
        {
            try
            {
                Assert.True(frameIndex < vector.Frames.Count, $"{id}: the decoder outputs more than the {vector.Frames.Count} expected frame(s).");
                AssertFrame(vector, frameIndex, scope, frame);
            }
            finally
            {
                frame.Release();
            }

            frameIndex++;
        }

        Assert.Equal(vector.FrameCount, frameIndex, message: $"{id}: the decoder does not output the expected number of frames.");
    }

    private static void AssertFrame(Av1VectorEntry vector, int frameIndex, AllocationScope scope, Av1FrameBuffer frame)
    {
        var name = $"{vector.Id} frame {frameIndex}";
        var expected = vector.Frames[frameIndex];
        var sequence = frame.Sequence;
        Assert.Equal(vector.BitDepth, sequence.BitDepth, message: $"{name}: bit depth.");
        Assert.Equal(vector.PlaneCount, frame.PlaneCount, message: $"{name}: number of planes.");
        if (frame.PlaneCount > 1)
        {
            var subsampling = (sequence.SubsamplingX, sequence.SubsamplingY) switch
            {
                (1, 1) => "4:2:0",
                (1, 0) => "4:2:2",
                (0, 0) => "4:4:4",
                _ => $"({sequence.SubsamplingX}, {sequence.SubsamplingY})",
            };
            Assert.Equal(vector.Subsampling, subsampling, message: $"{name}: chroma subsampling.");
        }

        var planes = CopyOutputPlanes(scope, frame);
        for (var plane = 0; plane < frame.PlaneCount; plane++)
        {
            // The plane dimensions of the manifest follow from the frame size: a chroma plane is (size + subsampling) >> subsampling
            var subsamplingX = plane > 0 ? sequence.SubsamplingX : 0;
            var subsamplingY = plane > 0 ? sequence.SubsamplingY : 0;
            var width = (expected.Width + subsamplingX) >> subsamplingX;
            var height = (expected.Height + subsamplingY) >> subsamplingY;
            var decoded = frame.GetPlane(plane);
            Assert.Equal((width, height), (decoded.Width, decoded.Height), message: $"{name} plane {PlaneNames[plane]}: plane size.");

            var actual = ComputeDigest(planes[plane], sequence.BitDepth);
            Assert.Equal(expected.Planes[plane], actual, message: $"{name} plane {PlaneNames[plane]} ({width}x{height}, {sequence.BitDepth}-bit) differs from dav1d and libaom (SHA-256 of the samples). Features: {string.Join(' ', vector.Features)}.");
        }
    }

    /// <summary>
    /// The planes of an output frame, tightly packed (plane width samples per row), with the film grain of the frame header
    /// applied by stripes of 32 luma rows, the way the AVIF decoder outputs a frame.
    /// </summary>
    private static ushort[][] CopyOutputPlanes(AllocationScope scope, Av1FrameBuffer frame)
    {
        var planes = new ushort[frame.PlaneCount][];
        for (var plane = 0; plane < frame.PlaneCount; plane++)
        {
            var source = frame.GetPlane(plane);
            planes[plane] = new ushort[source.Width * source.Height];
            for (var y = 0; y < source.Height; y++)
            {
                source.GetRow(y).CopyTo(planes[plane].AsSpan(y * source.Width, source.Width));
            }
        }

        if (frame.Header.FilmGrain is not { } parameters)
            return planes;

        var luma = frame.GetPlane(0);
        using var grain = new Av1FilmGrain(scope, frame.Sequence, parameters, luma.Width, luma.Height);
        var chromaWidth = frame.PlaneCount > 1 ? frame.GetPlane(1).Width : 0;
        var chromaRowsPerStripe = Av1FilmGrain.StripeHeight >> frame.Sequence.SubsamplingY;
        for (var stripe = 0; stripe < grain.StripeCount; stripe++)
        {
            var lumaRows = planes[0].AsSpan(stripe * Av1FilmGrain.StripeHeight * luma.Width);
            Span<ushort> uRows = default;
            Span<ushort> vRows = default;
            if (frame.PlaneCount > 1)
            {
                uRows = planes[1].AsSpan(stripe * chromaRowsPerStripe * chromaWidth);
                vRows = planes[2].AsSpan(stripe * chromaRowsPerStripe * chromaWidth);
            }

            grain.ApplyStripe(frame, stripe, lumaRows, luma.Width, uRows, vRows, chromaWidth);
        }

        return planes;
    }

    private static string ComputeDigest(ReadOnlySpan<ushort> samples, int bitDepth)
    {
        byte[] bytes;
        if (bitDepth == 8)
        {
            bytes = new byte[samples.Length];
            for (var i = 0; i < samples.Length; i++)
            {
                // A sample above the 8-bit range must not be hidden by the truncation: it changes the digest
                if (samples[i] > byte.MaxValue)
                    throw new XunitException($"An 8-bit plane has the sample {samples[i]} at index {i}.");

                bytes[i] = (byte)samples[i];
            }
        }
        else
        {
            bytes = new byte[samples.Length * 2];
            for (var i = 0; i < samples.Length; i++)
            {
                BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(i * 2), samples[i]);
            }
        }

        return Convert.ToHexStringLower(SHA256.HashData(bytes));
    }
}
